using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using Staybnb.Data;using Staybnb.Models;using Staybnb.Services;
namespace Staybnb.Controllers;
[Authorize]
public class BookingsController(ApplicationDbContext db,UserManager<ApplicationUser> users,ActivityLogger logger,IWebHostEnvironment env):Controller {
 [HttpGet,Authorize(Roles="Guest")] public async Task<IActionResult> Create(int propertyId){var p=await db.Properties.FirstOrDefaultAsync(x=>x.Id==propertyId&&x.IsActive);if(p==null)return NotFound();ViewBag.Property=p;return View(new BookingCreateViewModel{PropertyId=propertyId,CheckIn=DateTime.Today.AddDays(1),CheckOut=DateTime.Today.AddDays(2),Travelers=1});}
 [HttpPost,ValidateAntiForgeryToken,Authorize(Roles="Guest")] public async Task<IActionResult> Create(BookingCreateViewModel m){var p=await db.Properties.FirstOrDefaultAsync(x=>x.Id==m.PropertyId&&x.IsActive);if(p==null)return NotFound();ViewBag.Property=p;if(m.CheckIn.Date<DateTime.Today||m.CheckOut.Date<=m.CheckIn.Date)ModelState.AddModelError("","Choose valid future dates; check-out must be after check-in.");if(m.Travelers>p.MaxGuests)ModelState.AddModelError(nameof(m.Travelers),$"This property allows up to {p.MaxGuests} guests.");var overlap=await db.Bookings.AnyAsync(b=>b.PropertyId==p.Id&&b.Status!="Rejected"&&b.Status!="Cancelled"&&m.CheckIn.Date<b.CheckOut&&m.CheckOut.Date>b.CheckIn);if(overlap)ModelState.AddModelError("","Those dates overlap an existing booking request.");if(!ModelState.IsValid)return View(m);var nights=(m.CheckOut.Date-m.CheckIn.Date).Days;var total=p.PricePerNight*nights+p.CleaningFee+p.ServiceFee;var booking=new Booking{PropertyId=p.Id,GuestId=users.GetUserId(User)!,CheckIn=m.CheckIn.Date,CheckOut=m.CheckOut.Date,Travelers=m.Travelers,TotalPrice=total,PricePerNightSnapshot=p.PricePerNight};db.Bookings.Add(booking);await db.SaveChangesAsync();db.Notifications.Add(new Notification{UserId=p.HostId,Title="New booking request",Body=$"A guest requested {p.Title} from {m.CheckIn:d} to {m.CheckOut:d}.",Link="/HostApplications/Dashboard"});await db.SaveChangesAsync();await logger.LogAsync(booking.GuestId,"BookingCreated",$"Booking #{booking.Id} submitted; total {total:C}.","Booking",booking.Id.ToString());return RedirectToAction(nameof(Mine));}
 [Authorize(Roles="Guest,Host")] public async Task<IActionResult> Mine(){var uid=users.GetUserId(User);if(User.IsInRole("Host"))return RedirectToAction("Dashboard","HostApplications");return View(await db.Bookings.Include(b=>b.Property).ThenInclude(p=>p!.Images).Where(b=>b.GuestId==uid).OrderByDescending(b=>b.CreatedAt).ToListAsync());}
 [HttpPost,ValidateAntiForgeryToken,Authorize(Roles="Host")] public async Task<IActionResult> UpdateStatus(int id,string status){if(status is not("Approved" or "Rejected"))return BadRequest();var uid=users.GetUserId(User);var b=await db.Bookings.Include(x=>x.Property).FirstOrDefaultAsync(x=>x.Id==id&&x.Property!.HostId==uid);if(b==null)return NotFound();if(b.Status!="Pending")return BadRequest("Only pending bookings can be reviewed.");if(status=="Approved"){var overlap=await db.Bookings.AnyAsync(x=>x.PropertyId==b.PropertyId&&x.Id!=b.Id&&x.Status=="Approved"&&b.CheckIn<x.CheckOut&&b.CheckOut>x.CheckIn);if(overlap){TempData["Error"]="Cannot approve: another approved booking overlaps those dates.";return RedirectToAction("Dashboard","HostApplications");}}b.Status=status;db.Notifications.Add(new Notification{UserId=b.GuestId,Title="Booking "+status,Body=$"Your booking for {b.Property!.Title} was {status.ToLowerInvariant()}.",Link="/Bookings/Mine"});await db.SaveChangesAsync();await logger.LogAsync(uid,"BookingStatusChanged",$"Booking #{id} changed to {status}.","Booking",id.ToString());return RedirectToAction("Dashboard","HostApplications");}
 [HttpGet,Authorize(Roles="Guest")] public async Task<IActionResult> CheckIn(int id){var uid=users.GetUserId(User);var b=await db.Bookings.Include(x=>x.Property).FirstOrDefaultAsync(x=>x.Id==id&&x.GuestId==uid);if(b==null)return NotFound();if(b.Status!="Approved")return BadRequest("Check-in is available only for approved bookings.");ViewBag.Booking=b;ViewBag.CheckInProcess=await db.CheckInProcesses.FirstOrDefaultAsync(c=>c.PropertyId==b.PropertyId);ViewBag.Documents=await db.GuestDocuments.Where(d=>d.BookingId==id&&d.GuestId==uid).OrderByDescending(d=>d.UploadedAt).ToListAsync();return View();}
 [HttpPost,ValidateAntiForgeryToken,Authorize(Roles="Guest")] public async Task<IActionResult> UploadDocument(int id,IFormFile document,string documentType){var uid=users.GetUserId(User);var b=await db.Bookings.Include(x=>x.Property).FirstOrDefaultAsync(x=>x.Id==id&&x.GuestId==uid&&x.Status=="Approved");if(b==null)return NotFound();if(document==null||document.Length==0||document.Length>5*1024*1024){TempData["Error"]="Choose a document no larger than 5 MB.";return RedirectToAction(nameof(CheckIn),new{id});}var ext=Path.GetExtension(document.FileName).ToLowerInvariant();if(!new[]{".pdf",".jpg",".jpeg",".png"}.Contains(ext)){TempData["Error"]="Only PDF, JPG and PNG documents are accepted.";return RedirectToAction(nameof(CheckIn),new{id});}var folder=Path.Combine(env.ContentRootPath,"PrivateUploads");Directory.CreateDirectory(folder);var name=Guid.NewGuid().ToString("N")+ext;await using(var fs=System.IO.File.Create(Path.Combine(folder,name)))await document.CopyToAsync(fs);db.GuestDocuments.Add(new GuestDocument{BookingId=id,GuestId=uid,FilePath=name,DocumentType=documentType is "ID" or "Passport"?documentType:"Passport"});await db.SaveChangesAsync();await logger.LogAsync(uid,"GuestDocumentUploaded",$"Document uploaded for booking #{id}.","GuestDocument",id.ToString());return RedirectToAction(nameof(CheckIn),new{id});}
 [HttpPost,ValidateAntiForgeryToken,Authorize(Roles="Guest")] public async Task<IActionResult> CompleteCheckIn(int id){var uid=users.GetUserId(User);var b=await db.Bookings.FirstOrDefaultAsync(x=>x.Id==id&&x.GuestId==uid&&x.Status=="Approved");if(b==null)return NotFound();var doc=await db.GuestDocuments.AnyAsync(d=>d.BookingId==id&&d.GuestId==uid&&d.Status=="Verified");if(!doc){TempData["Error"]="The host must verify your uploaded document before check-in can be completed.";return RedirectToAction(nameof(CheckIn),new{id});}b.Status="CheckedIn";b.CheckedInAt=DateTime.UtcNow;await db.SaveChangesAsync();await logger.LogAsync(uid,"CheckInCompleted",$"Booking #{id} checked in.","Booking",id.ToString());return RedirectToAction(nameof(Mine));}
}